export {CUSTOM_METRICS,metricLimit} from './scenario-metrics.js?v=financial-advisor-1';
export function validateCustomDefinition(v,size=v?.mapSize??48){if(!MAP_SIZES.includes(size)||v?.mapSize!==undefined&&v.mapSize!==size)throw Error('Scenario map size does not match this city.');if(!v||typeof v.title!=='string'||!v.title.trim()||v.title.length>60||/[\x00-\x1f]/.test(v.title)||!Number.isInteger(v.months)||v.months<12||v.months>1200||!Array.isArray(v.objectives)||v.objectives.length<1||v.objectives.length>4)throw Error('Choose a title, a 12–1200 month deadline, and one to four goals.');const completionMode=v.completionMode??'goals';if(!['goals','scripted'].includes(completionMode))throw Error('Choose goal completion or scripted endings.');const objectiveMode=v.objectiveMode??'together';if(!['together','sequence'].includes(objectiveMode))throw Error('Choose simultaneous goals or sequential stages.');const eventMode=v.eventMode??'monthly';if(!['monthly','together'].includes(eventMode))throw Error('Choose one event per month or grouped actions.');const holdMonths=v.holdMonths??1;if(!Number.isInteger(holdMonths)||holdMonths<1||holdMonths>v.months)throw Error('Hold goals for 1 to the deadline’s number of months.');if(objectiveMode==='sequence'&&holdMonths*v.objectives.length>v.months)throw Error('The deadline must allow enough months to hold every stage.');const seen=new Set();const objectives=v.objectives.map((o,index)=>{const m=Object.hasOwn(CUSTOM_METRICS,o?.metric)?CUSTOM_METRICS[o.metric]:null;const area=validateScenarioArea(o.area,m,size),key=o.metric+JSON.stringify(area);if(!m||objectiveMode==='together'&&seen.has(key)||!Number.isFinite(o.target)||o.target<(m.min||0)||o.target>metricLimit(m,size)||m.integer&&!Number.isInteger(o.target))throw Error('Choose distinct goals with targets inside their allowed ranges.');if(o.addAtStartup!==undefined&&typeof o.addAtStartup!=='boolean')throw Error('Choose whether a goal is active at startup.');seen.add(key);return{...(o.addAtStartup===false?{addAtStartup:false}:{}),metric:o.metric,target:o.target,...validateGoalText(o,objectiveMode,index),...(area?{area}:{})};});const events=validateEventDefinitions(v.events,v.months,eventMode,size),compiled=compileGameScenarioPrograms(v.programs,{size,objectives}),programs=compiled.map(({name,steps})=>({name,steps})),actions=[...events,...reachableProgramActions(compiled,events.filter(e=>e.type==='program').map(e=>e.routine))];if(completionMode==='scripted'&&!actions.some(e=>e.type==='ending'))throw Error('A scripted challenge needs a reachable End scenario action.');if(events.some(e=>['addGoal','markGoal'].includes(e.type)&&e.goal>=objectives.length)||objectives.some((o,i)=>o.addAtStartup===false&&!actions.some(e=>e.type==='addGoal'&&e.goal===i)))throw Error('Every inactive goal needs an Add Goal event targeting an existing objective.');return validateGoalStatusReferences({...(programs.length?{programs}:{}),mapSize:size,completionMode,ranks:validateScenarioRanks(v.ranks,size),variables:validateScenarioVariables(v.variables),objectiveMode,eventMode,speed:validateScenarioSpeed(v.speed),backgroundRules:validateBackgroundRules(v.backgroundRules),...validateScenarioStory(v),title:v.title.trim(),months:v.months,holdMonths,objectives,events});}
function objectiveGoal(c,o){const mark=c.scenario.goalMarks?.[c.scenario.definition.objectives.indexOf(o)];const m=CUSTOM_METRICS[o.metric],value=m.read(c,o.area),requirement=`${m.name}${scenarioAreaLabel(o.area)}: ${m.states?m.states[o.target]:(m.date?'on or after':m.direction)+' '+formatScenarioMetric(m,o.target,20)}`;return{...(o.area?{area:o.area}:{}),title:o.name||requirement,instructions:goalInstructions(o,c),done:mark?mark.satisfied:m.direction==='equals'?value===o.target:m.direction==='at least'?value>=o.target:value<=o.target,detail:`${mark?'Scripted status: '+(mark.satisfied?'satisfied':'unsatisfied')+'. ':''}${o.name?'Requirement: '+requirement+'. ':''}Current: ${m.states?m.states[value]:formatScenarioMetric(m,value)}`};}

export function customCurrentGoals(c){const s=c.scenario,sequence=s.definition.objectiveMode==='sequence',completed=s.stageCompletedMonths?.length||0;return [...scenarioEventGoals(c),...s.definition.objectives.map((o,i)=>{if(!goalIsActive(s,i))return null;if(sequence&&o.revealWhenActive&&i>completed&&s.status==='playing')return null;const g=objectiveGoal(c,o);if(!sequence)return g;return {...g,title:`Stage ${i+1} · ${g.title}`,done:c.scenario.goalMarks?.[i]?.satisfied??(i<completed),detail:i<completed?`${g.detail} · Completed in challenge month ${s.stageCompletedMonths[i]-s.startMonth}. Completion is retained.`:i===completed?`${g.detail} · Hold: ${s.streak} / ${s.definition.holdMonths} consecutive months.`:g.detail+' · Locked until the preceding stage is completed.'};}).filter(Boolean)];}
export function attachCustomScenario(c,definition){if(c.emergency.active)throw Error('Finish the active emergency before creating a challenge.');const d=validateCustomDefinition(definition,mapSize(c));c.scenario={id:'custom',definition:d,textOverrides:{},...(d.programs?{programInvocations:[]}:{}),startingCity:captureScenarioStart(c),rankOutcome:null,goalMarks:initialGoalMarks(d),goalActivatedMonths:initialGoalActivations(d,c.month),variables:d.variables.map(v=>v.initial),events:d.events.map(()=>({status:'pending',month:null,runs:0})),stageCompletedMonths:[],status:'playing',startMonth:c.month,lastChecked:c.month,streak:0,eventFired:false,endedMonth:null,rank:null};return c.scenario;}

export function advanceCustomStreak(c){const s=c.scenario;if(s.definition.objectiveMode==='sequence'){const completed=s.stageCompletedMonths.length;if(completed>=s.definition.objectives.length)return;if(!goalIsActive(s,completed)){s.streak=0;return;}s.streak=!c.emergency.active&&objectiveGoal(c,s.definition.objectives[completed]).done?Math.min(s.definition.holdMonths,s.streak+1):0;if(s.streak>=s.definition.holdMonths){s.stageCompletedMonths.push(c.month);s.streak=0;}return;}s.streak=s.definition.objectives.some((o,i)=>goalIsActive(s,i))&&(s.definition.completionMode==='scripted'?s.definition.objectives.filter((o,i)=>goalIsActive(s,i)).map(o=>objectiveGoal(c,o)):customCurrentGoals(c)).every(g=>g.done)?Math.min(s.definition.holdMonths,s.streak+1):0;}
export function customGoals(c){const s=c.scenario,goals=customCurrentGoals(c);if(!s.definition.objectives.some((o,i)=>goalIsActive(s,i)))goals.unshift({title:'Await scenario instructions',done:false,detail:'No goal is active yet. Continue until an Add Goal event introduces an objective.'});if(s.definition.objectiveMode==='sequence'){const completed=s.stageCompletedMonths.length;goals.unshift({title:`Complete ${s.definition.objectives.length} stages in order`,done:completed===s.definition.objectives.length,detail:`${completed} / ${s.definition.objectives.length} completed. Each stage needs ${s.definition.holdMonths} consecutive monthly checks. Finished stages stay complete; required events must still finish before victory.`});}else if(s.definition.holdMonths>1)goals.unshift({title:`Hold every goal for ${s.definition.holdMonths} consecutive months`,done:s.streak>=s.definition.holdMonths,detail:`${s.streak} / ${s.definition.holdMonths} months. Missing a goal resets progress; required events and emergency response must finish before the streak begins.`});return goals;}
export function validateStageProgress(v,definition,startMonth,lastChecked,streak,status,scriptedWin=false){if(definition.objectiveMode==='sequence'&&!Array.isArray(v))throw Error('Missing scenario stage progress.');const stages=v??[];if(!Array.isArray(stages)||stages.length>definition.objectives.length||definition.objectiveMode!=='sequence'&&stages.length||stages.some((month,i)=>!Number.isInteger(month)||month>(lastChecked)||month-(i?stages[i-1]:startMonth)<definition.holdMonths)||definition.objectiveMode==='sequence'&&(streak>=definition.holdMonths||streak>lastChecked-(stages.at(-1)??startMonth)||stages.length===definition.objectives.length&&streak!==0||status==='won'&&!scriptedWin&&stages.length!==definition.objectives.length))throw Error('Invalid scenario stage progress.');return [...stages];}
